        let css = ":root { --primary: #111111; --link: #2389d7; --sidebar-badge: #ff0000; }";
        let parsed = UiTheme::from_shadcn_css(css, ThemeMode::Light).unwrap();
        assert_eq!(parsed.colors.link(), gpui_kit::rgb(0x2389d7));
        assert_eq!(parsed.colors.sidebar_badge(), gpui_kit::rgb(0xff0000));
        assert_eq!(parsed.colors.mention_highlight(), gpui_kit::rgb(0x111111));
    }

    #[test]
    fn converts_pinned_neutral_tokens() {
        assert_eq!(
            neutral(1.0),
            Rgba {
                r: 1.0,
                g: 1.0,
                b: 1.0,
                a: 1.0,
            }
        );
        assert_eq!(
            neutral(0.0),
            Rgba {
                r: 0.0,
                g: 0.0,
                b: 0.0,
                a: 1.0,
            }
        );

        assert_eq!(neutral_light_colors().destructive, srgb(0xdc, 0x26, 0x26));
        assert_eq!(neutral_dark_colors().destructive, srgb(0xff, 0x64, 0x67));
        assert_eq!(
            neutral_dark_colors().sidebar_primary,
            srgb(0x14, 0x47, 0xe6)
        );
    }

    fn close(left: Rgba, right: Rgba) -> bool {
        [
            (left.r, right.r),
            (left.g, right.g),
            (left.b, right.b),
            (left.a, right.a),
        ]
        .iter()
        .all(|(left, right)| (left - right).abs() < 1.5 / 255.)
    }

    #[test]
    fn imports_shadcn_theme_css() {
        let css = r#"
            @layer base {
              :root {
                --radius: 0.5rem; /* 8px */
                --background: oklch(1 0 0);
                --foreground: oklch(0.145 0 0);
                --primary: #2563eb;
                --ring: rgb(37 99 235 / 50%);
                --sidebar-background: 0 0% 98%;
                --font-sans: Inter, sans-serif;
              }
              .dark {
                --background: oklch(0.145 0 0);
                --border: oklch(1 0 0 / 10%);
                --sidebar-primary: oklch(0.488 0.243 264.376);
                --chart-1: hsl(220 70% 50%);
              }
            }
        "#;
        let light = UiTheme::from_shadcn_css(css, ThemeMode::Light).unwrap();
        assert_eq!(light.mode, ThemeMode::Light);
        assert_eq!(light.radius.lg, px(8.));
        assert!(close(light.colors.background, neutral(1.0)));
        assert!(close(light.colors.foreground, neutral(0.145)));
        assert_eq!(light.colors.primary, srgb(0x25, 0x63, 0xeb));
        assert!(close(
            light.colors.ring,
            Rgba {
                a: 0.5,
                ..srgb(37, 99, 235)
            }
        ));
        assert!(close(light.colors.sidebar, neutral(0.985)));
        // Variables the CSS leaves out keep the Neutral defaults.
        assert_eq!(light.colors.muted, neutral_light_colors().muted);

        let dark = UiTheme::from_shadcn_css(css, ThemeMode::Dark).unwrap();
        assert_eq!(dark.mode, ThemeMode::Dark);
        assert!(close(dark.colors.background, neutral(0.145)));
        // `.dark` inherits `:root` values it does not override.
        assert_eq!(dark.colors.primary, srgb(0x25, 0x63, 0xeb));
        assert!(close(dark.colors.border, neutral_alpha(1.0, 0.10)));
        assert!(close(dark.colors.sidebar_primary, srgb(0x14, 0x47, 0xe6)));
        assert!(close(dark.colors.chart_1, srgb(0x26, 0x63, 0xd9)));

        assert!(UiTheme::from_shadcn_css(":root { --primary: blue; }", ThemeMode::Light).is_err());
        assert!(UiTheme::from_shadcn_css(":root { --radius: 1em; }", ThemeMode::Light).is_err());
        assert!(UiTheme::from_shadcn_css(":root { }", ThemeMode::Dark).is_err());
        assert_eq!(
            css_hex("fff8"),
            Some(Rgba {
                r: 1.,
                g: 1.,
                b: 1.,
                a: 0x88 as f32 / 255.
            })
        );
    }

    #[test]
    fn preserves_pinned_alpha_tokens() {
        let dark = neutral_dark_colors();
        assert_eq!(dark.border.a, 0.10);
        assert_eq!(dark.input.a, 0.15);
        assert_eq!(dark.sidebar_border.a, 0.10);
        assert!((dark.input.opacity(0.30).a - 0.045).abs() < f32::EPSILON);
    }

    #[test]
    fn derives_the_shadcn_radius_and_shadow_scales() {
        let theme = UiTheme::neutral_light();
        assert_eq!(theme.radius.sm, px(6.));
        assert_eq!(theme.radius.md, px(8.));
        assert_eq!(theme.radius.lg, px(10.));
        assert_eq!(theme.radius.xl, px(14.));
        assert_eq!(theme.shadows.sm.len(), 2);
        assert_eq!(theme.shadows.md.len(), 2);
        assert_eq!(theme.shadows.lg.len(), 2);
    }

    #[gpui_kit::test]
    fn keeps_component_state_tokens_in_sync_with_ui_theme(cx: &mut gpui_kit::TestAppContext) {
        cx.update(|cx| {
            init(cx);
            let component = gpui_kit::component::Theme::global(cx);
            assert_eq!(component.mode, gpui_kit::component::ThemeMode::Light);
            assert_eq!(
                component.button_hover,
                UiTheme::read(cx).colors.accent.into()
            );

            UiTheme::switch(cx, ThemeMode::Dark);
            let component = gpui_kit::component::Theme::global(cx);
            assert_eq!(component.mode, gpui_kit::component::ThemeMode::Dark);
            assert_eq!(component.ring, UiTheme::read(cx).colors.ring.into());

            let mut custom = UiTheme::read(cx).clone();
            custom.colors.accent = srgb(0x22, 0x66, 0xaa);
            custom.fonts.body = "Custom Sans".into();
            custom.radius = UiRadius::new(px(12.));
            let expected_accent = custom.colors.accent;
            UiTheme::set(cx, custom);

            let component = gpui_kit::component::Theme::global(cx);
            assert_eq!(component.button_hover, expected_accent.into());
            assert_eq!(component.font_family, "Custom Sans");
            assert_eq!(component.radius, px(9.6));
            assert_eq!(
                component.tokens.button_hover.background,
                expected_accent.into()
            );

            init(cx);
            assert_eq!(
                gpui_kit::component::Theme::global(cx).button_hover,
                expected_accent.into()
            );
        });
    }
}

// Refine the actual control after default styling; no extra layout or focus node.
#[doc(hidden)]
pub fn apply_style<T: Styled>(mut element: T, style: &gpui_kit::StyleRefinement) -> T {
    use gpui_kit::Refineable as _;
    element.style().refine(style);
    element
}

#[derive(gpui_kit::IntoElement)]
#[doc(hidden)]
pub struct DisclosureIcon {
    icon: gpui_kit::Svg,
    open: bool,
}
#[doc(hidden)]
pub fn disclosure_icon(icon: gpui_kit::Svg, open: bool) -> DisclosureIcon {
    DisclosureIcon { icon, open }
}
impl gpui_kit::RenderOnce for DisclosureIcon {
    fn render(self, window: &mut Window, cx: &mut App) -> impl gpui_kit::IntoElement {
        let duration = UiTheme::read(cx).motion.fast;
        let value = transition_value(
            "disclosure-rotation",
            if self.open { 1. } else { 0. },
            duration,
            window,
            cx,
        );
        self.icon
            .with_transformation(gpui_kit::Transformation::rotate(gpui_kit::radians(
                value * std::f32::consts::PI,
            )))
    }
}

#[cfg(test)]
mod motion_tests {
    use super::*;
    use gpui_kit::{
        AppContext as _, Context, IntoElement, Render, TestAppContext, VisualTestContext, div,
    };

    struct View {
        target: f32,
        sampled: f32,
    }
    impl Render for View {
        fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            self.sampled = transition_value(
                "test-motion",
                self.target,
                Duration::from_millis(200),
                window,
                cx,
            );
            div()
        }
    }

    #[gpui_kit::test]
    fn theme_reduced_motion_snaps_an_active_upstream_transition(cx: &mut TestAppContext) {
        cx.update(init);
        let window = cx.add_window(|_, _| View {
            target: 0.,
            sampled: 0.,
        });
        let mut visual = VisualTestContext::from_window(window.into(), cx);
        visual.update(|window, cx| window.draw(cx).clear(cx));
        window
            .update(cx, |view, _, cx| {
                view.target = 1.;
                cx.notify();
            })
            .unwrap();
        visual.update(|window, cx| window.draw(cx).clear(cx));
        assert_eq!(
            cx.read_window(&window, |view, cx| view.read(cx).sampled)
                .unwrap(),
            0.
        );
        cx.update(|cx| {
            let mut theme = UiTheme::read(cx).clone();
            theme.motion.reduced = true;
            UiTheme::set(cx, theme);
        });
        visual.update(|window, cx| window.draw(cx).clear(cx));
        assert_eq!(
            cx.read_window(&window, |view, cx| view.read(cx).sampled)
                .unwrap(),
            1.
        );
    }
}

/// Shared focus traversal for the tab, radio and toggle collections.
#[doc(hidden)]
pub struct RovingFocus {
    pub handles: Vec<Option<gpui_kit::FocusHandle>>,
    active: gpui_kit::Entity<Option<gpui_kit::FocusHandle>>,
}
impl RovingFocus {
    pub fn new(
        id: gpui_kit::ElementId,
        items: &[(gpui_kit::ElementId, bool)],
        selected: Option<usize>,
        window: &mut gpui_kit::Window,
        cx: &mut App,
    ) -> Self {
        let active =
            window.use_keyed_state((id, "active"), cx, |_, _| None::<gpui_kit::FocusHandle>);
        let mut handles: Vec<_> = items
            .iter()
            .map(|(id, disabled)| {
                let handle = window
                    .use_keyed_state((id.clone(), "focus"), cx, |_, cx| cx.focus_handle())
                    .read(cx)
                    .clone();
                handle.clone().tab_stop(false);
                (!disabled).then_some(handle)
            })
            .collect();
        let index = handles
            .iter()
            .position(|h| h.as_ref().is_some_and(|h| h.is_focused(window)))
            .or(selected.filter(|&i| handles.get(i).is_some_and(Option::is_some)))
            .or_else(|| {
                handles
                    .iter()
                    .position(|h| h.is_some() && h.as_ref() == active.read(cx).as_ref())
            })
            .or_else(|| handles.iter().position(Option::is_some));
        if let Some(index) = index {
            let handle = handles[index].as_ref().unwrap().clone().tab_stop(true);
            handles[index] = Some(handle.clone());
            active.update(cx, |value, _| *value = Some(handle));
        }
        Self { handles, active }
    }
    pub fn key(
        &self,
        event: &gpui_kit::KeyDownEvent,
        axis: Option<gpui_kit::Axis>,
        window: &mut gpui_kit::Window,
        cx: &mut App,
    ) -> Option<usize> {
        if event.keystroke.modifiers.modified() {
            return None;
        }
        let enabled: Vec<_> = self
            .handles
            .iter()
            .enumerate()
            .filter_map(|(i, h)| h.as_ref().map(|h| (i, h)))
            .collect();
        let current = enabled.iter().position(|(_, h)| h.is_focused(window))?;
        let direction = UiTheme::read(cx).direction;
        let next = match direction.logical_key(event.keystroke.key.as_str()) {
            "home" => 0,
            "end" => enabled.len() - 1,
            "left" if axis != Some(gpui_kit::Axis::Vertical) => {
                (current + enabled.len() - 1) % enabled.len()
            }
            "right" if axis != Some(gpui_kit::Axis::Vertical) => (current + 1) % enabled.len(),
            "up" if axis != Some(gpui_kit::Axis::Horizontal) => {
                (current + enabled.len() - 1) % enabled.len()
            }
            "down" if axis != Some(gpui_kit::Axis::Horizontal) => (current + 1) % enabled.len(),
            _ => return None,
        };
        enabled[current].1.clone().tab_stop(false);
        let handle = enabled[next].1.clone().tab_stop(true);
        handle.focus(window, cx);
        self.active.update(cx, |value, _| *value = Some(handle));
        window.refresh();
        cx.stop_propagation();
        Some(enabled[next].0)
    }
}

//! The shadcn Nova Button visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `button.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction comes from the
//! GPUI Kit headless button.

use std::rc::Rc;

use gpui_kit::base::Button as BaseButton;
use gpui_kit::{
    AnyElement, App, ClickEvent, ElementId, FontWeight, IntoElement, ParentElement, RenderOnce,
    Rgba, SharedString, Styled, Window, px,
};

use super::theme::{
    UiRadius, UiTheme,
    locale::DirectionalStyled as _,
    primitives::{disabled as disabled_style, focus},
};

type ButtonClickHandler = Rc<dyn Fn(&ClickEvent, &mut Window, &mut App) + 'static>;
type ButtonStyleHandler = Rc<dyn Fn(BaseButton) -> BaseButton>;

/// The pinned shadcn Button visual variant.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonVariant {
    /// Primary action.
    #[default]
    Default,
    /// Bordered action.
    Outline,
    /// Secondary action.
    Secondary,
    /// Low-emphasis action.
    Ghost,
    /// Destructive action.
    Destructive,
    /// Link-styled action.
    Link,
}

/// The pinned shadcn Button size.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonSize {
    /// 24px-high extra-small button.
    Xs,
    /// 28px-high small button.
    Sm,
    /// 32px-high default button.
    #[default]
    Default,
    /// 36px-high large button.
    Lg,
    /// 24px square icon button.
    IconXs,
    /// 28px square icon button.
    IconSm,
    /// 32px square icon button.
    Icon,
    /// 36px square icon button.
    IconLg,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ButtonMetrics {
    height: f32,
    horizontal_padding: f32,
    gap: f32,
    radius: f32,
    text_size: f32,
    icon_only: bool,
}

impl ButtonSize {
    fn metrics(self, radii: UiRadius) -> ButtonMetrics {
        let radius = f32::from(radii.lg);
        let radius_md = f32::from(radii.md);
        match self {
            Self::Xs => ButtonMetrics::new(24.0, 8.0, 4.0, radius_md.min(10.0), 12.0, false),
            Self::Sm => ButtonMetrics::new(28.0, 10.0, 4.0, radius_md.min(12.0), 12.8, false),
            Self::Default => ButtonMetrics::new(32.0, 10.0, 6.0, radius, 14.0, false),
            Self::Lg => ButtonMetrics::new(36.0, 10.0, 6.0, radius, 14.0, false),
            Self::IconXs => ButtonMetrics::new(24.0, 0.0, 0.0, radius_md.min(10.0), 14.0, true),
            Self::IconSm => ButtonMetrics::new(28.0, 0.0, 0.0, radius_md.min(12.0), 14.0, true),
            Self::Icon => ButtonMetrics::new(32.0, 0.0, 0.0, radius, 14.0, true),
            Self::IconLg => ButtonMetrics::new(36.0, 0.0, 0.0, radius, 14.0, true),
        }
    }
}

impl ButtonMetrics {
    const fn new(
        height: f32,
        horizontal_padding: f32,
        gap: f32,
        radius: f32,
        text_size: f32,
        icon_only: bool,
    ) -> Self {
        Self {
            height,
            horizontal_padding,
            gap,
            radius,
            text_size,
            icon_only,
        }
    }
}

/// A styled Button that keeps GPUI Kit's pointer and keyboard behavior.
#[derive(IntoElement)]
pub struct Button {
    style: gpui_kit::StyleRefinement,
    id: ElementId,
    variant: ButtonVariant,
    size: ButtonSize,
    disabled: bool,
    aria_label: Option<SharedString>,
    on_click: Option<ButtonClickHandler>,
    style_with: Option<ButtonStyleHandler>,
    tint: Option<Rgba>,
    children: Vec<AnyElement>,
}

impl Button {
    /// Creates a Button with a caller-owned stable ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui_kit::StyleRefinement::default(),
            id: id.into(),
            variant: ButtonVariant::default(),
            size: ButtonSize::default(),
            disabled: false,
            aria_label: None,
            on_click: None,
            style_with: None,
            tint: None,
            children: Vec::new(),
        }
    }

    /// Sets the visual variant.
    pub fn variant(mut self, variant: ButtonVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Sets the visual size.
    pub fn size(mut self, size: ButtonSize) -> Self {
        self.size = size;
        self
    }

    /// Prevents activation and removes the Button from tab order.
    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    /// Sets the accessible name for icon or custom content. Use `label` for plain text.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Adds visible text and uses it as the accessible name unless one was supplied.
    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        let label = label.into();
        self.aria_label.get_or_insert_with(|| label.clone());
        self.children.push(label.into_any_element());
        self
    }

    /// Runs for pointer, Enter, or Space activation.
    pub fn on_click(
        mut self,
        handler: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_click = Some(Rc::new(handler));
        self
    }

    /// Fills the button with one app-chosen color, such as an integration's
    /// `#3f51b5`. Hover moves the fill toward the text, and the text is the
    /// theme's foreground or background, whichever reads better on the fill,
    /// so it keeps its contrast in light and dark mode. Replaces the variant.
    pub fn tint(mut self, color: impl Into<Rgba>) -> Self {
        self.tint = Some(color.into());
        self
    }

    /// Replaces the visual styling while retaining button interaction.
    /// Include a visible keyboard focus treatment in custom styles.
    pub fn style_with(mut self, handler: impl Fn(BaseButton) -> BaseButton + 'static) -> Self {
        self.style_with = Some(Rc::new(handler));
        self
    }
}

impl ParentElement for Button {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.children.extend(elements);
    }
}

impl RenderOnce for Button {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let variant = self.variant;
        let size = self.size;
        let root = BaseButton::new(self.id).disabled(self.disabled);
        let root = match (self.style_with, self.tint) {
            (Some(style), _) => style(root),
            (None, Some(tint)) => style_tinted_button(root, self.disabled, tint, size, &theme),
            (None, None) => style_button(root, self.disabled, variant, size, &theme),
        };
        let mut root = super::theme::apply_style(root, &self.style).children(self.children);

        if let Some(label) = self.aria_label {
            root = root.accessibility_label(label);
        }
        if let Some(handler) = self.on_click {
            root = root.on_click(move |event, window, cx| handler(event, window, cx));
        }

        root
    }
}

#[doc(hidden)]
pub fn style_button<T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder>(
    base: T,
    disabled: bool,
    variant: ButtonVariant,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    style_button_with(base, disabled, variant, None, size, theme)
}

fn style_button_with<
    T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder,
>(
    base: T,
    disabled: bool,
    variant: ButtonVariant,
    tint: Option<Rgba>,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    let colors = theme.colors;
    let control = theme.control();
    let metrics = size.metrics(theme.radius);
    let invalid_ring = variant == ButtonVariant::Destructive;
    let focus_theme = theme.clone();

    let base = base
        .flex_row_in(theme.direction)
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .whitespace_nowrap()
        .h(theme.space(metrics.height / 4.))
        .gap(theme.space(metrics.gap / 4.))
        .rounded(px(metrics.radius))
        .border_1()
        .border_color(colors.background.opacity(0.0))
        .font_family(theme.fonts.body.clone())
        .font_weight(FontWeight::MEDIUM)
        .text_size(theme.text(metrics.text_size))
        .focus_visible(move |style| focus::ring_for(style, &focus_theme, invalid_ring))
        .when(metrics.icon_only, |base| {
            base.w(theme.space(metrics.height / 4.)).p_0()
        })
        .when(!metrics.icon_only, |base| {
            base.px(theme.space(metrics.horizontal_padding / 4.))
        });

    if let Some(tint) = tint {
        let (fill, hover, foreground) = tint_colors(tint, theme);
        let base = base
            .bg(fill)
            .text_color(foreground)
            .when(!disabled, |base| base.hover(move |style| style.bg(hover)));
        return disabled_style::interactive(base, disabled);
    }
    let base = match variant {
        ButtonVariant::Default => base
            .bg(colors.primary)
            .text_color(colors.primary_foreground)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(colors.primary.opacity(0.80)))
            }),
        ButtonVariant::Outline => base
            .bg(control.background)
            .text_color(colors.foreground)
            .border_color(control.border)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(control.hover).text_color(colors.foreground))
            }),
        ButtonVariant::Secondary => {
            let hover = colors
                .secondary
                .blend(colors.secondary_foreground.opacity(0.08));
            base.bg(colors.secondary)
                .text_color(colors.secondary_foreground)
                .when(!disabled, |base| base.hover(move |style| style.bg(hover)))
        }
        ButtonVariant::Ghost => base
            .bg(colors.background.opacity(0.0))
            .text_color(colors.foreground)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(control.ghost_hover).text_color(colors.foreground))
            }),
        ButtonVariant::Destructive => base
            .bg(control.destructive_background)
            .text_color(colors.destructive)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(control.destructive_hover))
            }),
        ButtonVariant::Link => base
            .bg(colors.background.opacity(0.0))
            .text_color(colors.primary)
            .when(!disabled, |base| base.hover(|style| style.underline())),
    };

    disabled_style::interactive(base, disabled)
}

/// WCAG relative luminance of an opaque color.
fn luminance(color: Rgba) -> f32 {
    let channel = |c: f32| {
        if c <= 0.039_28 {
            c / 12.92
        } else {
            ((c + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * channel(color.r) + 0.7152 * channel(color.g) + 0.0722 * channel(color.b)
}

/// The WCAG contrast ratio between two opaque colors, from 1 to 21.
pub fn contrast_ratio(a: Rgba, b: Rgba) -> f32 {
    let (a, b) = (luminance(a), luminance(b));
    (a.max(b) + 0.05) / (a.min(b) + 0.05)
}

/// The fill, hover fill and text of a button tinted with `tint`.
pub fn tint_colors(tint: Rgba, theme: &UiTheme) -> (Rgba, Rgba, Rgba) {
    let fill = theme.opaque(tint);
    let colors = theme.colors;
    let foreground =
        if contrast_ratio(fill, colors.foreground) >= contrast_ratio(fill, colors.background) {
            colors.foreground
        } else {
            colors.background
        };
    let hover = fill.blend(foreground.opacity(0.14));
    (fill, hover, foreground)
}

#[doc(hidden)]
pub fn style_tinted_button<
    T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder,
>(
    base: T,
    disabled: bool,
    tint: Rgba,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    style_button_with(
        base,
        disabled,
        ButtonVariant::Default,
        Some(tint),
        size,
        theme,
    )
}

impl gpui_kit::Styled for Button {
    fn style(&mut self) -> &mut gpui_kit::StyleRefinement {
        &mut self.style
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tints_pick_readable_text_in_both_themes() {
        let indigo = Rgba::try_from("#3f51b5").unwrap();
        let lime = Rgba::try_from("#cddc39").unwrap();
        for theme in [UiTheme::neutral_light(), UiTheme::neutral_dark()] {
            for tint in [indigo, lime] {
                let (fill, hover, text) = tint_colors(tint, &theme);
                assert!(contrast_ratio(fill, text) >= 4.5, "{tint:?} reads");
                assert_ne!(fill, hover);
            }
            let (_, _, text) = tint_colors(indigo, &theme);
            assert!(luminance(text) > 0.5, "indigo takes light text");
            let (_, _, text) = tint_colors(lime, &theme);
            assert!(luminance(text) < 0.1, "lime takes dark text");
        }
    }

    #[test]
    fn all_variants_expose_clickable_and_disabled_cursors() {
        for theme in [UiTheme::neutral_light(), UiTheme::neutral_dark()] {
            for variant in [
                ButtonVariant::Default,
                ButtonVariant::Outline,
                ButtonVariant::Secondary,
                ButtonVariant::Ghost,
                ButtonVariant::Destructive,
                ButtonVariant::Link,
            ] {
                for disabled in [false, true] {
                    let mut button = style_button(
                        gpui_kit::div(),
                        disabled,
                        variant,
                        ButtonSize::Default,
                        &theme,
                    );
                    assert_eq!(
                        button.style().mouse_cursor,
                        Some(if disabled {
                            gpui_kit::CursorStyle::OperationNotAllowed
                        } else {
                            gpui_kit::CursorStyle::PointingHand
                        })
                    );
                }
            }
        }
    }

    #[test]
    fn nova_sizes_are_exact() {
        let sizes = [
            (ButtonSize::Xs, 24.0, 8.0, 4.0, 8.0),
            (ButtonSize::Sm, 28.0, 10.0, 4.0, 8.0),
            (ButtonSize::Default, 32.0, 10.0, 6.0, 10.0),
            (ButtonSize::Lg, 36.0, 10.0, 6.0, 10.0),
            (ButtonSize::IconXs, 24.0, 0.0, 0.0, 8.0),
            (ButtonSize::IconSm, 28.0, 0.0, 0.0, 8.0),
            (ButtonSize::Icon, 32.0, 0.0, 0.0, 10.0),
            (ButtonSize::IconLg, 36.0, 0.0, 0.0, 10.0),
        ];

        for (size, height, padding, gap, radius) in sizes {
            let metrics = size.metrics(UiRadius::new(px(10.0)));
            assert_eq!(metrics.height, height);
            assert_eq!(metrics.horizontal_padding, padding);
            assert_eq!(metrics.gap, gap);
            assert_eq!(metrics.radius, radius);
        }
    }
}

//! Nova notifications using Kit's toast queue, timers and measured stack.
use super::{
    button::{Button, ButtonSize, ButtonVariant},
    theme::{
        Direction, UiText, UiTheme,
        locale::{self, DirectionalStyled as _},
        primitives::{surface, text},
    },
};
use gpui_icons::{LucideIcon, lucide};
use gpui_kit::base::{
    Toast, ToastManager, ToastMotion, ToastOptions, ToastStack, ToastStackState,
    ToastTransitionStatus,
};
use gpui_kit::{
    Anchor, App, Context, ElementId, FocusHandle, FontWeight, InteractiveElement as _, IntoElement,
    ParentElement as _, Pixels, Render, SharedString, Styled, Task, Window, div, px,
};
use std::{rc::Rc, time::Duration};
use web_time::Instant;

type ActionHandler = Rc<dyn Fn(&mut Window, &mut App) + 'static>;
type DismissHandler = Rc<dyn Fn(NoticeDismissal, &mut App) + 'static>;

/// Why a notification left the screen, passed to `Notice::on_dismiss`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum NoticeDismissal {
    /// The reader pressed the `action` button.
    Action,
    /// The reader pressed the `cancel` button, such as "Later".
    Cancel,
    /// The reader pressed the close button.
    Close,
    /// The timeout ran out.
    Timeout,
    /// The app called `ToastState::dismiss`.
    Dismissed,
    /// The app pushed another notification with the same ID.
    Replaced,
}

impl NoticeDismissal {
    /// Returns whether the reader dismissed the notification themselves, with
    /// the cancel or close button.
    pub fn by_reader(self) -> bool {
        matches!(self, Self::Cancel | Self::Close)
    }
}

/// Where the stack sits in the window, set with `ToastState::set_placement`.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ToastPlacement {
    /// Top left corner; new notifications enter at the top.
    TopLeft,
    /// Top edge, centered.
    TopCenter,
    /// Top right corner.
    TopRight,
    /// Bottom left corner, the default; new notifications enter at the bottom.
    #[default]
    BottomLeft,
    /// Bottom edge, centered.
    BottomCenter,
    /// Bottom right corner.
    BottomRight,
}

impl ToastPlacement {
    /// The corner on screen: left and right are the reading start and end,
    /// so they swap in right-to-left layouts.
    pub fn physical(self, direction: Direction) -> Self {
        if !direction.is_rtl() {
            return self;
        }
        match self {
            Self::TopLeft => Self::TopRight,
            Self::TopRight => Self::TopLeft,
            Self::BottomLeft => Self::BottomRight,
            Self::BottomRight => Self::BottomLeft,
            other => other,
        }
    }

    fn anchor(self) -> Anchor {
        match self {
            Self::TopLeft => Anchor::TopLeft,
            Self::TopCenter => Anchor::TopCenter,
            Self::TopRight => Anchor::TopRight,
            Self::BottomLeft => Anchor::BottomLeft,
            Self::BottomCenter => Anchor::BottomCenter,
            Self::BottomRight => Anchor::BottomRight,
        }
    }
}

/// One notification: a title, optional description, up to two buttons and an
/// auto-dismiss timeout.
#[derive(Clone)]
pub struct Notice {
    title: SharedString,
    description: SharedString,
    timeout: Option<Duration>,
    action: Option<(SharedString, ActionHandler)>,
    cancel: Option<SharedString>,
    on_dismiss: Option<DismissHandler>,
}
impl std::fmt::Debug for Notice {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Notice")
            .field("title", &self.title)
            .field("description", &self.description)
            .field("timeout", &self.timeout)
            .field("action", &self.action.as_ref().map(|(label, _)| label))
            .field("cancel", &self.cancel)
            .field("on_dismiss", &self.on_dismiss.is_some())
            .finish()
    }
}
impl Notice {
    /// Creates a notification that dismisses itself after five seconds.
    pub fn new(title: impl Into<SharedString>) -> Self {
        Self {
            title: title.into(),
            description: SharedString::default(),
            timeout: Some(Duration::from_secs(5)),
            action: None,
            cancel: None,
            on_dismiss: None,
        }
    }
    /// Adds a button, such as "Undo", "Retry" or "Show in folder". Pressing it
    /// runs `handler` and dismisses the notification. Hovering the stack
    /// pauses the timeout so the button can be reached.
    pub fn action(
        mut self,
        label: impl Into<SharedString>,
        handler: impl Fn(&mut Window, &mut App) + 'static,
    ) -> Self {
        self.action = Some((label.into(), Rc::new(handler)));
        self
    }
    /// Adds a secondary button, such as "Dismiss", that only closes the notification.
    pub fn cancel(mut self, label: impl Into<SharedString>) -> Self {
        self.cancel = Some(label.into());
        self
    }
    /// Runs once when the notification starts to leave, with the reason, so
    /// the app can tell "Later" or the close button apart from the action or
    /// a timeout. It runs after the current update, so it may push again.
    pub fn on_dismiss(mut self, handler: impl Fn(NoticeDismissal, &mut App) + 'static) -> Self {
        self.on_dismiss = Some(Rc::new(handler));
        self
    }
    /// Secondary text below the title.
    pub fn description(mut self, description: impl Into<SharedString>) -> Self {
        self.description = description.into();
        self
    }
    /// Dismisses the notification after `timeout`.
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }
    /// Keeps the notification until the user dismisses it.
    pub fn persistent(mut self) -> Self {
        self.timeout = None;
        self
    }
}
/// Poll interval while a hovered stack holds its timers, the only state the
/// manager cannot announce ahead of time.
const PAUSED_POLL: Duration = Duration::from_millis(100);

/// Own this entity in the application and mount it once above the page content.
pub struct ToastState {
    manager: ToastManager<SharedString, Notice>,
    motion: ToastMotion,
    stack: ToastStackState,
    focus: FocusHandle,
    /// When each mounted toast next changes phase, by ID. Entry and exit
    /// transitions end after the motion durations; a shown toast ends when its
    /// timeout runs out, which a hovered stack pushes back.
    deadlines: Vec<(SharedString, Instant)>,
    timer: Option<Task<()>>,
    placement: ToastPlacement,
    inset: Option<(Pixels, Pixels)>,
}
impl ToastState {
    /// Creates an empty notification queue and its focus handle.
    pub fn new(cx: &mut Context<Self>) -> Self {
        let motion = ToastMotion::sonner();
        Self {
            manager: ToastManager::new(motion),
            motion,
            stack: Default::default(),
            focus: cx.focus_handle(),
            deadlines: Vec::new(),
            timer: None,
            placement: ToastPlacement::default(),
            inset: None,
        }
    }
    /// Moves the stack to another corner or edge of the window.
    pub fn set_placement(&mut self, placement: ToastPlacement, cx: &mut Context<Self>) {
        self.placement = placement;
        cx.notify();
    }
    /// Sets the stack's distance from the window's side and from its top or
    /// bottom edge, such as to clear a composer. The default is 16px each.
    pub fn set_inset(&mut self, horizontal: Pixels, vertical: Pixels, cx: &mut Context<Self>) {
        self.inset = Some((horizontal, vertical));
        cx.notify();
    }
    /// Returns whether a notification with this ID is queued or on screen and
    /// not already leaving.
    pub fn contains(&self, id: &str) -> bool {
        self.manager
            .iter()
            .any(|(other, _, phase)| other.as_ref() == id && phase != ToastTransitionStatus::Ending)
    }
    /// Replaces an existing ID or adds a new notification.
    pub fn push(&mut self, id: impl Into<SharedString>, notice: Notice, cx: &mut Context<Self>) {
        let id = id.into();
        let timeout = notice.timeout;
        let now = Instant::now();
        let showing = self.contains(&id);
        let replaced = self
            .manager
            .push(id.clone(), notice, ToastOptions { timeout }, now);
        if let Some(replaced) = replaced.filter(|_| showing) {
            Self::notify_dismissed(&replaced, NoticeDismissal::Replaced, cx);
        }
        self.set_deadline(id, now + self.motion.duration);
        self.schedule(cx);
        cx.notify();
    }
    /// Removes the notification with this ID.
    pub fn dismiss(&mut self, id: &SharedString, cx: &mut Context<Self>) {
        self.dismiss_with(id, NoticeDismissal::Dismissed, cx);
    }
    fn dismiss_with(&mut self, id: &SharedString, reason: NoticeDismissal, cx: &mut Context<Self>) {
        let now = Instant::now();
        if self.manager.dismiss(id, now) {
            if let Some(notice) = self.manager.get(id) {
                Self::notify_dismissed(notice, reason, cx);
            }
            self.set_deadline(id.clone(), now + self.motion.exit_duration);
            self.schedule(cx);
            cx.notify();
        }
    }
    fn notify_dismissed(notice: &Notice, reason: NoticeDismissal, cx: &mut App) {
        if let Some(handler) = notice.on_dismiss.clone() {
            cx.defer(move |cx| handler(reason, cx));
        }
    }
    fn set_deadline(&mut self, id: SharedString, at: Instant) {
        self.deadlines.retain(|(other, _)| *other != id);
        self.deadlines.push((id, at));
    }
    /// Moves the manager's clock forward and records when it next needs to move.
    fn advance(&mut self, now: Instant, cx: &mut Context<Self>) {
        let paused = self.stack.is_expanded();
        let advance = self.manager.advance(now, paused);
        for id in advance.presented {
            match self.manager.get(&id).and_then(|notice| notice.timeout) {
                Some(timeout) => self.set_deadline(id, now + timeout),
                None => self.deadlines.retain(|(other, _)| *other != id),
            }
        }
        for id in advance.ending {
            if let Some(notice) = self.manager.get(&id) {
                Self::notify_dismissed(notice, NoticeDismissal::Timeout, cx);
            }
            self.set_deadline(id, now + self.motion.exit_duration);
        }
        for (id, _) in &advance.removed {
            self.deadlines.retain(|(other, _)| other != id);
        }
        if advance.changed {
            cx.notify();
        }
    }
    /// Sleeps until the next deadline, or polls while a hover pauses the timers.
    fn schedule(&mut self, cx: &mut Context<Self>) {
        let now = Instant::now();
        let next = self.deadlines.iter().map(|(_, at)| *at).min();
        let Some(next) = next else {
            self.timer = None;
            return;
        };
        let wait = if self.stack.is_expanded() {
            PAUSED_POLL
        } else {
            next.saturating_duration_since(now) + Duration::from_millis(1)
        };
        self.timer = Some(cx.spawn(async move |this, cx| {
            cx.background_executor().timer(wait).await;
            this.update(cx, |state, cx| {
                let now = Instant::now();
                if state.stack.is_expanded() {
                    // Shown toasts hold their remaining time while hovered; keep
                    // their deadlines moving with the clock.
                    let shown: Vec<SharedString> = state
                        .manager
                        .iter()
                        .filter(|(_, _, phase)| *phase == ToastTransitionStatus::Present)
                        .map(|(id, _, _)| id.clone())
                        .collect();
                    for (id, at) in &mut state.deadlines {
                        if shown.contains(id) {
                            *at += wait;
                        }
                    }
                }
                state.advance(now, cx);
                state.schedule(cx);
            })
            .ok();
        }));
    }
    /// Returns whether the notification queue is empty.
    pub fn is_empty(&self) -> bool {
        self.manager.is_empty()
    }
}
impl Render for ToastState {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let colors = theme.colors;
        let viewport = window.viewport_size();
        let (inset_x, inset_y) = self.inset.unwrap_or((theme.space(4.), theme.space(4.)));
        let width = (viewport.width - inset_x * 2.).min(theme.space(96.));
        let dir = theme.direction;
        let placement = self.placement.physical(dir);
        let close_label = locale::text(cx, UiText::CloseNotification);
        let mut stack = ToastStack::new("toasts", self.stack.clone())
            .placement(placement.anchor())
            .focus_handle(self.focus.clone())
            .absolute()
            .w(width);
        stack = match placement {
            ToastPlacement::TopLeft | ToastPlacement::BottomLeft => stack.left(inset_x),
            ToastPlacement::TopRight | ToastPlacement::BottomRight => stack.right(inset_x),
            ToastPlacement::TopCenter | ToastPlacement::BottomCenter => {
                stack.left((viewport.width - width) / 2.)
            }
        };
        stack = match placement {
            ToastPlacement::TopLeft | ToastPlacement::TopCenter | ToastPlacement::TopRight => {
                stack.top(inset_y)
            }
            _ => stack.bottom(inset_y),
        };
        for (id, notice, phase) in self.manager.visible(3) {
            let dismiss = id.clone();
            let state = cx.entity().downgrade();
            let button = |key: &'static str,
                          label: SharedString,
                          variant: ButtonVariant,
                          reason: NoticeDismissal,
                          handler: Option<ActionHandler>| {
                let dismiss = id.clone();
                let state = state.clone();
                Button::new(ElementId::from((ElementId::from(id.clone()), key)))
                    .variant(variant)
                    .size(ButtonSize::Xs)
                    .label(label)
                    .on_click(move |_, window, cx| {
                        if let Some(handler) = &handler {
                            handler(window, cx);
                        }
                        state
                            .update(cx, |state, cx| state.dismiss_with(&dismiss, reason, cx))
                            .ok();
                    })
            };
            // In tab order the buttons come before the close button.
            let buttons = (notice.action.is_some() || notice.cancel.is_some()).then(|| {
                div()
                    .flex_row_in(dir)
                    .items_center()
                    .gap(theme.space(2.))
                    .pt(theme.space(2.))
                    .children(notice.action.clone().map(|(label, handler)| {
                        button(
                            "action",
                            label,
                            ButtonVariant::Default,
                            NoticeDismissal::Action,
                            Some(handler),
                        )
                    }))
                    .children(notice.cancel.clone().map(|label| {
                        button(
                            "cancel",
                            label,
                            ButtonVariant::Outline,
                            NoticeDismissal::Cancel,
                            None,
                        )
                    }))
            });
            let close = Button::new(ElementId::from((ElementId::from(id.clone()), "close")))
                .aria_label(close_label.clone())
                .variant(ButtonVariant::Ghost)
                .size(ButtonSize::IconSm)
                .absolute()
                .top(theme.space(2.))
                .inset_end(dir, theme.space(2.))
                .on_click(move |_, _, cx| {
                    state
                        .update(cx, |state, cx| {
                            state.dismiss_with(&dismiss, NoticeDismissal::Close, cx)
                        })
                        .ok();
                })
                .child(
                    lucide(LucideIcon::X)
                        .size(theme.space(4.))
                        .text_color(colors.muted_foreground),
                );
            let presence = super::theme::presence(
                ElementId::from((ElementId::from(id.clone()), "presence")),
                phase != ToastTransitionStatus::Ending,
                window,
                cx,
            );
            let toast = Toast::new(id.clone())
                .transition_status(phase)
                .relative()
                .occlude()
                .w_full();
            let toast = surface::toast(toast, &theme)
                .p(theme.space(4.))
                .padding_end(dir, theme.space(12.))
                .flex()
                .flex_col()
                .gap(theme.space(1.))
                .opacity(presence.progress)
                .child(
                    div()
                        .font_weight(FontWeight::MEDIUM)
                        .child(notice.title.clone()),
                )
                .child(text::muted(div(), &theme).child(notice.description.clone()))
                .children(buttons)
                .child(close);
            stack = stack.item(id.clone(), toast);
        }
        gpui_kit::deferred(
            gpui_kit::anchored()
                .position(gpui_kit::point(px(0.), px(0.)))
                .child(div().w(viewport.width).h(viewport.height).child(stack)),
        )
        .with_priority(20)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui_kit::{AppContext as _, TestAppContext};

    fn phases(state: &ToastState) -> Vec<(SharedString, ToastTransitionStatus)> {
        state
            .manager
            .iter()
            .map(|(id, _, phase)| (id.clone(), phase))
            .collect()
    }

    #[gpui_kit::test]
    fn notices_present_time_out_and_leave_on_their_deadlines(cx: &mut TestAppContext) {
        cx.update(super::super::theme::init);
        let state = cx.update(|cx| cx.new(ToastState::new));
        let start = Instant::now();
        state.update(cx, |state, cx| {
            state.push(
                "saved",
                Notice::new("Saved").timeout(Duration::from_secs(2)),
                cx,
            );
            state.push("pinned", Notice::new("Pinned").persistent(), cx);
            assert_eq!(state.deadlines.len(), 2, "both wait for their entry motion");
            assert!(state.timer.is_some());

            state.advance(start + Duration::from_millis(401), cx);
            assert!(
                phases(state)
                    .iter()
                    .all(|(_, phase)| *phase == ToastTransitionStatus::Present)
            );
            // Only the timed notice still has a deadline.
            assert_eq!(state.deadlines.len(), 1);
            assert_eq!(state.deadlines[0].0, "saved");

            state.advance(start + Duration::from_millis(2402), cx);
            assert_eq!(
                phases(state),
                [
                    ("saved".into(), ToastTransitionStatus::Ending),
                    ("pinned".into(), ToastTransitionStatus::Present)
                ]
            );
            state.advance(start + Duration::from_millis(2603), cx);
            assert_eq!(
                phases(state),
                [("pinned".into(), ToastTransitionStatus::Present)]
            );
            assert!(state.deadlines.is_empty());

            state.dismiss(&"pinned".into(), cx);
            assert_eq!(state.deadlines.len(), 1);
            state.advance(start + Duration::from_millis(2804), cx);
            assert!(state.is_empty());
            state.schedule(cx);
            assert!(state.timer.is_none(), "nothing left to wait for");
        });
    }

    /// Tab from the stack reaches a notice's action before its close button,
    /// and pressing it runs the handler and dismisses the notice
    /// (devaryakjha/gpuicn#95).
    #[gpui_kit::test]
    fn an_action_runs_and_dismisses_its_notice(cx: &mut TestAppContext) {
        use gpui_kit::{KeyDownEvent, KeyUpEvent, Keystroke};
        cx.update(super::super::theme::init);
        let ran = Rc::new(std::cell::Cell::new(0));
        let count = ran.clone();
        let (state, cx) = cx.add_window_view(|window, cx| {
            window.activate_window();
            ToastState::new(cx)
        });
        state.update(cx, |state, cx| {
            state.push(
                "download",
                Notice::new("review-notes.pdf")
                    .description("Saved to Downloads")
                    .persistent()
                    .action("Show in folder", move |_, _| count.set(count.get() + 1))
                    .cancel("Dismiss"),
                cx,
            )
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));
        cx.update(|window, cx| {
            let focus = state.read(cx).focus.clone();
            focus.focus(window, cx);
            window.draw(cx).clear(cx);
        });
        cx.simulate_keystrokes("tab");
        cx.update(|window, cx| window.draw(cx).clear(cx));
        let keystroke = Keystroke::parse("enter").unwrap();
        cx.simulate_event(KeyDownEvent {
            keystroke: keystroke.clone(),
            is_held: false,
            prefer_character_input: false,
        });
        cx.simulate_event(KeyUpEvent { keystroke });
        assert_eq!(ran.get(), 1, "the action ran");
        state.update(cx, |state, _| {
            assert!(
                state
                    .manager
                    .iter()
                    .all(|(_, _, phase)| phase == ToastTransitionStatus::Ending),
                "the notice is leaving"
            );
        });
    }

    type Reasons = Rc<std::cell::RefCell<Vec<(&'static str, NoticeDismissal)>>>;

    fn record(reasons: &Reasons, id: &'static str) -> impl Fn(NoticeDismissal, &mut App) + use<> {
        let reasons = reasons.clone();
        move |reason, _| reasons.borrow_mut().push((id, reason))
    }

    /// The app hears why each notice left and can ask whether one is still
    /// showing (devaryakjha/gpuicn#122).
    #[gpui_kit::test]
    fn on_dismiss_reports_timeouts_replacements_and_dismissals(cx: &mut TestAppContext) {
        cx.update(super::super::theme::init);
        let reasons = Reasons::default();
        let state = cx.update(|cx| cx.new(ToastState::new));
        let start = Instant::now();
        state.update(cx, |state, cx| {
            state.push(
                "saved",
                Notice::new("Saved")
                    .timeout(Duration::from_secs(2))
                    .on_dismiss(record(&reasons, "saved")),
                cx,
            );
            state.push(
                "update",
                Notice::new("Update ready")
                    .persistent()
                    .on_dismiss(record(&reasons, "first update")),
                cx,
            );
            assert!(state.contains("saved") && state.contains("update"));
            assert!(!state.contains("other"));
            // Pushing the same ID again replaces the notice.
            state.push(
                "update",
                Notice::new("Update ready")
                    .persistent()
                    .on_dismiss(record(&reasons, "update")),
                cx,
            );
            state.advance(start + Duration::from_millis(401), cx);
            state.advance(start + Duration::from_millis(2402), cx);
            assert!(
                !state.contains("saved"),
                "a leaving notice no longer counts"
            );
            assert!(state.contains("update"));
            state.dismiss(&"update".into(), cx);
            assert!(!state.contains("update"));
            // A second dismissal of a leaving notice reports nothing.
            state.dismiss(&"update".into(), cx);
        });
        let reported = reasons.borrow().clone();
        assert_eq!(
            reported,
            [
                ("first update", NoticeDismissal::Replaced),
                ("saved", NoticeDismissal::Timeout),
                ("update", NoticeDismissal::Dismissed),
            ]
        );
    }

    /// "Later" and the close button report that the reader dismissed the
    /// notice, which the action does not (devaryakjha/gpuicn#122).
    #[gpui_kit::test]
    fn buttons_report_which_one_dismissed_the_notice(cx: &mut TestAppContext) {
        use gpui_kit::{KeyDownEvent, KeyUpEvent, Keystroke};
        cx.update(super::super::theme::init);
        let reasons = Reasons::default();
        let (state, cx) = cx.add_window_view(|window, cx| {
            window.activate_window();
            ToastState::new(cx)
        });
        let press = |cx: &mut gpui_kit::VisualTestContext, tabs: usize| {
            cx.update(|window, cx| {
                let focus = state.read(cx).focus.clone();
                focus.focus(window, cx);
                window.draw(cx).clear(cx);
            });
            for _ in 0..tabs {
                cx.simulate_keystrokes("tab");
                cx.update(|window, cx| window.draw(cx).clear(cx));
            }
            let keystroke = Keystroke::parse("enter").unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
        };
        let notice = |id: &'static str| {
            Notice::new("Update ready")
                .persistent()
                .action("Restart to update", |_, _| {})
                .cancel("Later")
                .on_dismiss(record(&reasons, id))
        };
        // Tab order: action, cancel, close.
        for (id, tabs) in [("action", 1), ("later", 2), ("close", 3)] {
            state.update(cx, |state, cx| state.push(id, notice(id), cx));
            cx.update(|window, cx| window.draw(cx).clear(cx));
            press(cx, tabs);
            cx.run_until_parked();
            assert!(!state.read_with(cx, |state, _| state.contains(id)));
            // Let the notice leave so the next one is alone in the stack.
            state.update(cx, |state, cx| {
                state.advance(Instant::now() + Duration::from_secs(1), cx)
            });
        }
        let reported = reasons.borrow().clone();
        assert_eq!(
            reported,
            [
                ("action", NoticeDismissal::Action),
                ("later", NoticeDismissal::Cancel),
                ("close", NoticeDismissal::Close),
            ]
        );
        assert!(NoticeDismissal::Cancel.by_reader() && !NoticeDismissal::Action.by_reader());
    }
}
